# typed: true
# frozen_string_literal: true

require "English"
require "serviceowners"

require "github/config"

module GitHub
  class Serviceowners
    class GenerateServiceFiles

      DEFAULT_OWNERSHIP_PATH = GitHub::AppEnvironment.root.join("ownership.yaml").freeze

      CODEOWNERS_HEADER = <<~EOS
        ### Generated by bin/generate-service-files.rb from SERVICEOWNERS.
        ### DO NOT MANUALLY EDIT THIS FILE! Instead edit SERVICEOWNERS.
      EOS

      OWNERSHIP_HEADER = <<~EOS
        ### Generated by bin/generate-service-files.rb from config/service-mappings.yaml.
        ### DO NOT MANUALLY EDIT THIS FILE! Instead edit config/service-mappings.yaml.
      EOS

      # The cache exists to speed up service determination for production code, typically from the context of a
      # request or job. As such, configuration, test, db, and library files will never need to know the service
      # to which they belong, at least not in a timely manner. These can be skipped to reduce the size of the cache.
      SKIPPED_DIRECTORIES = [
        ".github/",
        "config/kubernetes",
        "db/",
        "lib/github/transitions/",
        "lib/hydro/schemas/",
        "public/",
        "test/",
        "vendor/"
      ].freeze

      PACKAGE_TEST_REGEX = %r{\Apackages/[^/]+/test/}.freeze


      def initialize(
        service_mappings_path = GitHub::Serviceowners::DEFAULT_SERVICE_MAPPINGS_PATH,
        serviceowners_path = GitHub::Serviceowners::DEFAULT_SERVICEOWNERS_PATH
      )
        @service_mappings_path = service_mappings_path
        @serviceowners_path = serviceowners_path
      end

      def self.run!(profile: false, cache_only: false)
        new.run!(profile: profile, cache_only: cache_only)
      end

      def run!(profile: false, cache_only: false)
        start_profiling! if profile

        validate!
        if cache_only
          generate_cache_files!
        else
          generate_project_files!
        end

      ensure
        generate_profiling_data! if profile
      end

      private

      def generate_project_files!
        generate_codeowners!
        generate_ownership_yaml!
        generate_service_links!
      end

      def generate_cache_files!
        puts "==> Generating cache files..."
        generate_serviceowners_cache!
        generate_serviceowners_class_cache!
      end

      def generate_serviceowners_cache!
        # no indentation to reduce size
        # pretty print to aid Git merge resolution
        data = serviceowners_main.path_data.build_path_cache.sort.to_h
        cache_json = GitHub::JSON.encode(data, pretty: true, indent: "")
        GitHub::Serviceowners::CACHE_PATH.write(cache_json)
      end

      def generate_serviceowners_class_cache!
        class_cache = cache_path_data.build_class_cache

        # no indentation to reduce size
        # pretty print to aid Git merge resolution
        class_cache_json = GitHub::JSON.encode(class_cache, pretty: true, indent: "")
        GitHub::Serviceowners::CLASS_CACHE_PATH.write(class_cache_json)
      end

      def generate_codeowners!
        puts "==> Generating CODEOWNERS..."
        codeowners_contents = serviceowners_main.to_codeowners(1)
        GitHub::AppEnvironment.root.join("CODEOWNERS").write(CODEOWNERS_HEADER + codeowners_contents + "\n")
      end

      def generate_ownership_yaml!(ownership_path = DEFAULT_OWNERSHIP_PATH)
        puts "==> Generating ownership.yaml..."
        ownership_data = serviceowners_main.to_ownership.to_yaml(line_width: -1) # Do not wrap YAML
        ownership_path.write(OWNERSHIP_HEADER + ownership_data)
      end

      def generate_service_links!
        puts "==> Generating docs/index.yaml..."
        service_mappings_links = serviceowners_main.to_service_links.to_yaml(line_width: -1) # Do not wrap YAML
        GitHub::AppEnvironment.root.join("docs").join("index.yaml").write(OWNERSHIP_HEADER + service_mappings_links)
      end

      def validate!
        puts "==> Validating service configuration files..."
        serviceowners_main.validate!

        validate_at_most_one_shared_package_per_service!
      end

      def validate_at_most_one_shared_package_per_service!
        paths = serviceowners_main.paths.select { |p| p.start_with?("packages/") }
        path_data = ::Serviceowners::PathData.new(paths, serviceowners_main.service_patterns)

        services_to_packages = {}
        packages_to_services = {}

        path_data.path_specs.reverse_each do |path, spec|
          raise "#{path} has no spec!" if spec.nil?
          next unless spec.service

          package = path.split("/")[1]
          service = spec.service.name
          services_to_packages[service] ||= []
          services_to_packages[service] << package unless services_to_packages[service].include?(package)

          packages_to_services[package] ||= []
          packages_to_services[package] << service unless packages_to_services[package].include?(service)
        end

        packages_owned_by_multiple_services = packages_to_services.select { |_, services| services.size > 1 }.keys.flatten
        services_to_packages.each do |service, packages|
          packages_owned_by_other_services = packages.intersection(packages_owned_by_multiple_services)
          if packages_owned_by_other_services.size > 1
            file_list = path_data
              .path_specs
              .filter_map { |path, spec| path if spec.service.name == service }
              .join("\n  - ")

            out = <<~EOS
              The service #{service} owns files in multiple packages (#{packages_owned_by_other_services.join(", ")} which are also owned by other services.
              A service can have at most one shared package. Please update SERVICEOWNERS to ensure
              at most one shared package is assigned to the service.

              The following files match the service `#{service}`:
                - #{file_list}
            EOS

            raise out
          end
        end
      end

      def cache_path_data
        return @cache_path_data if defined?(@cache_path_data)

        paths = serviceowners_main.paths.dup
        paths.reject! do |path|
          next true unless path.end_with?(".rb")
          next true if path.start_with?(*SKIPPED_DIRECTORIES)
          next true if path.match?(PACKAGE_TEST_REGEX)

          false
        end

        @cache_path_data = ::Serviceowners::PathData.new(paths, serviceowners_main.service_patterns)
      end

      def serviceowners_main
        return @serviceowners_main if defined?(@serviceowners_main)

        runtime = ::Serviceowners::RuntimeEnv.new(
          mappings_path: @service_mappings_path,
          patterns_path: @serviceowners_path,
          base_ref: "origin/master",
          validate_mappings: true,
          validate_patterns: true
        )

        @serviceowners_main = ::Serviceowners::Main.new(runtime_env: runtime)
      end

      def generate_profiling_data!
        StackProf.stop
        puts "==> Generating stackprof outputs"
        output_basename = "tmp/generate-service-files-stackprof"
        output_dump = "#{output_basename}.dump"
        output_json = "#{output_basename}.json"

        StackProf.results(output_dump)
        system "stackprof --json #{output_dump} > #{output_json}"
        puts "JSON: #{output_json}"
      end

      def start_profiling!
        require "stackprof"
        StackProf.start(mode: :wall, raw: true)
      end
    end
  end
end
